ruleToc.chapterList:
@js:
const sx = JSON.parse(result);
const { novel: { volumes: vo }, volumes: cx } = sx.data;
cx.reduce(function(acc, v, i) {
  acc.push({ text: vo[i].name, volume: true });
  v.forEach(function(c) {
    acc.push({
      text: java.t2s(c.chapterName),
      href: `@js:getUrl("/chapter/detail", "content", "${c.novelId}", "${c.chapterId}")`
    });
  });
  return acc;
}, []);
